SysDataModelXML.SQLScript:
#LINKSCRIPTGET@DATAQA: DECLARE @DOCNUM VARCHAR(30) = '{0}'; DECLARE @MFGNUM VARCHAR(30); DECLARE @ROUOPE INT; DECLARE @LINKMSG NVARCHAR(500) = '';
SELECT @MFGNUM = MFGNUM , @ROUOPE = ROUOPE FROM QAINSPH H WHERE H.DOCNUM = @DOCNUM;
IF EXISTS (SELECT TOP 1 1 FROM x3v12sql.ERASTEEL.XWSMKOES WHERE MFGNUM_0 = @MFGNUM AND OPENUM_0 = @ROUOPE) BEGIN SELECT N'LINKPREVENT:已经存在报工记录，不可重复同步。' LINKMESSAGE END ELSE BEGIN SELECT CASE WHEN STA = 0 THEN N'LINKPREVENT:检验未完成，不可同步。' WHEN STA = 1 THEN N'LINKCONFIRM:有不合格记录，是否确认同步？' ELSE '' END LINKMESSAGE FROM QAINSPH WHERE DOCNUM = @DOCNUM; END #

SysDataModelXML.SQLClear:
DECLARE @DOCNUM VARCHAR(30) = '{0}';
DECLARE @USER VARCHAR(30) = '#LOGIN_USER#';
-- 
DECLARE @MFGNUM VARCHAR(30);
DECLARE @OPENUM INT;

SELECT @MFGNUM = MFGNUM
    , @OPENUM = ROUOPE
FROM QAINSPH
WHERE DOCNUM = @DOCNUM;

UPDATE #LC.X3DATA#MFGOPE
SET XESMMTRKSTA_0 = 5
WHERE MFGNUM_0 = @MFGNUM
    AND OPENUM_0 = @OPENUM;

UPDATE #LC.X3DATA#MFGOPE  
SET XESMMTRKSTA_0 = 3 
WHERE  MFGNUM_0 + CONVERT(VARCHAR(10), OPENUM_0) = 
	(SELECT TOP 1 MFGNUM_0 + CONVERT(VARCHAR(10), O.OPENUM_0) 
		FROM #LC.X3DATA#MFGOPE O 
		WHERE MFGNUM_0 = @MFGNUM AND OPENUM_0 > @OPENUM ORDER BY OPENUM_0);

UPDATE QAINSPH
SET CLOSTA = 1
    , CLOTIM = GETDATE()
    , CLOUSR = @USER
WHERE DOCNUM = @DOCNUM;
